// --- ARTICLE CARD ---
function ArticleCard({ article, level }) {
  const cardRef = React.useRef();
  const [sheenDir, setSheenDir] = React.useState('right');

  function handleMouseEnter(e) {
    const rect = cardRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    if (x < rect.width / 2) {
      setSheenDir('right'); // left side, animate right
    } else {
      setSheenDir('left'); // right side, animate left
    }
  }

  return (
    <Link
              to={`/learn/${level}/${article.id}`}
      className="article-card"
      aria-label={`Read article: ${article.title}`}
      ref={cardRef}
      data-sheen-direction={sheenDir}
      onMouseEnter={handleMouseEnter}
      style={{
        background: "#18232f",
        borderRadius: 28,
        border: "2px solid #36ff95",
        boxShadow: "0 0 32px #0bbfdb1A",
        padding: "20px 28px 28px 28px",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        width: "100%",
        maxWidth: 480,
        minWidth: 280,
        height: 444,
        color: "#fff",
        textDecoration: "none",
        margin: "1px auto 0 auto",
        transition: "box-shadow 0.17s, border 0.14s",
        position: "relative",
        boxSizing: "border-box"
      }}
      onMouseOver={e => { e.currentTarget.style.boxShadow = "0 0 42px #36ff95AA"; }}
      onMouseOut={e => { e.currentTarget.style.boxShadow = "0 0 32px #0bbfdb1A"; }}
    >
      {/* Image */}
              <div
          className="article-card-img-wrap"
          style={{
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            marginBottom: 18,
            width: "100%",
            maxWidth: 182,
            height: "auto",
            aspectRatio: "1/1",
            borderRadius: 26,
            background: "#22304a",
            boxShadow: "0 0 12px #36ff9522"
          }}>
        <img
          src={article.cover}
          alt={`Cover for ${article.title}`}
          className="article-card-img"
          style={{
            width: "100%",
            maxWidth: 160,
            height: "auto",
            aspectRatio: "1/1",
            borderRadius: 22,
            objectFit: "cover",
            objectPosition: "center",
            boxShadow: "0 0 28px #36ff95AA",
            display: "block"
          }}
          onError={(e) => {
            e.target.onerror = null;
            e.target.src = '/og-square.png';
          }}
        />
      </div>
      {/* Title */}
      <div style={{
        fontWeight: 900,
        color: "#36ff95",
        fontSize: "1.45rem",
        marginBottom: 9,
        lineHeight: 1.17,
        textAlign: "center"
      }}>
        {article.title}
      </div>
      {/* Date */}
      <div style={{
        color: "#79f2c1",
        fontSize: "1.12rem",
        fontWeight: 500,
        marginBottom: 18,
        textAlign: "center"
      }}>
        {article.date}
      </div>
      {/* Spacer to push Read More button to bottom */}
      <div style={{ flexGrow: 1 }}></div>
      {/* Read More Button */}
      <span className="read-more-btn" tabIndex={0}>
        Read More
      </span>
    </Link>
  );
}

